-- 012: catalogul validat de alimente (generat de scripts/build_food_catalog.py din USDA FoodData Central SR Legacy).
-- NU edita de mână: modifică data/food_catalog_spec.py și regenerează. Idempotent (upsert pe food_key).
begin;
on conflict (food_key) where food_key is not null do update set fdc_id = excluded.fdc_id, data_source = excluded.data_source, validated = excluded.validated, name = excluded.name, name_en = excluded.name_en, category = excluded.category, category_key = excluded.category_key, portion_g = excluded.portion_g, portion_label_ro = excluded.portion_label_ro, portion_label_en = excluded.portion_label_en, animal_source = excluded.animal_source, allergen_codes = excluded.allergen_codes, flags = excluded.flags, calories = excluded.calories, protein = excluded.protein, fat = excluded.fat, carbs = excluded.carbs, fiber = excluded.fiber, sugars = excluded.sugars, alcohol = excluded.alcohol, cholesterol = excluded.cholesterol, calcium = excluded.calcium, iron = excluded.iron, magnesium = excluded.magnesium, phosphorus = excluded.phosphorus, potassium = excluded.potassium, sodium = excluded.sodium, zinc = excluded.zinc, iodine = excluded.iodine, vitamin_a = excluded.vitamin_a, vitamin_d = excluded.vitamin_d, vitamin_c = excluded.vitamin_c, vitamin_b12 = excluded.vitamin_b12, vitamin_k = excluded.vitamin_k, folate = excluded.folate;
commit;
